// ttft.ts — time-to-first-token timer registry and assistant provenance.
//
// Per-session timer set at the start of a chat round (the first conversation
// model request; admission alone never arms it). Cleared on the first
// verified assistant-generated output of the round: a nonempty text or
// reasoning part, a streamed text delta, or a tool part / tool call. V1 part
// events count only when their message row was identified by an earlier
// message.updated as an assistant row of the same session; V2 stream events
// are assistant-generated by event type. User parts, metadata parts, and
// empty output never clear. If the timer fires before verified output
// arrives, the orchestrator is invoked with reason="ttft_timeout".
//
// Streaming-safe: once any verified output arrives, the timer is cleared and
// no further TTFT enforcement happens for that round. Inter-token stall
// detection is out of scope per agreement. The provenance registry below is
// bounded, and a session's rows are dropped on session.deleted.

export type TimerHandle = ReturnType<typeof setTimeout>;

interface TimerEntry {
  handle: TimerHandle;
}

export class TtftRegistry {
  private timers = new Map<string, TimerEntry>();

  arm(sessionId: string, ttftMs: number, onTimeout: () => void): void {
    // Replace any existing timer for the same session.
    this.clear(sessionId);
    const entry: TimerEntry = {
      handle: setTimeout(() => {
        if (this.timers.get(sessionId) !== entry) return;
        this.timers.delete(sessionId);
        onTimeout();
      }, ttftMs),
    };
    this.timers.set(sessionId, entry);
  }

  clear(sessionId: string): void {
    const entry = this.timers.get(sessionId);
    if (entry) {
      clearTimeout(entry.handle);
      this.timers.delete(sessionId);
    }
  }

  has(sessionId: string): boolean {
    return this.timers.has(sessionId);
  }
}

// Ceiling on recorded assistant-row provenance. Each row is two short
// strings; the bound keeps the map a fixed size over a long-lived process
// while covering any realistic window of concurrent messages.
const PROVENANCE_MAX_ROWS = 4096;

/**
 * messageID → sessionID provenance for the assistant rows observed on
 * message.updated. The V1 TTFT clear is provenance-gated: a part or delta
 * event clears the timer only when its messageID was identified as an
 * assistant row of the same session, so user parts, unidentified parts, and
 * foreign-session parts can never clear a timer. Insertion-ordered with
 * oldest-row eviction at the bound; dropSession removes the rows of a
 * deleted session.
 */
export class AssistantProvenance {
  private rows = new Map<string, string>();

  record(messageId: string, sessionId: string): void {
    this.rows.delete(messageId);
    this.rows.set(messageId, sessionId);
    if (this.rows.size > PROVENANCE_MAX_ROWS) {
      const oldest = this.rows.keys().next();
      if (oldest.done !== true) this.rows.delete(oldest.value);
    }
  }

  verified(messageId: string, sessionId: string): boolean {
    return this.rows.get(messageId) === sessionId;
  }

  dropSession(sessionId: string): void {
    for (const [messageId, owner] of this.rows) {
      if (owner === sessionId) this.rows.delete(messageId);
    }
  }
}
